mapper.select:
SELECT o.order_id, o.total_amount, o.order_status, o.payment_method, o.billing_key, o.created_at,
o.tracking_number, m.member_id AS member_id, m.name AS member_name, m.phone AS member_phone, m.email AS member_email,
p.name AS product_name, oi.order_price, oi.count FROM orders o LEFT JOIN member m ON o.member_id = m.member_id LEFT JOIN order_item oi ON o.order_id = oi.order_id LEFT JOIN product p ON oi.product_id = p.product_id WHERE o.order_id = #{orderId}

mapper.update:
UPDATE orders
SET order_status = #{orderStatus}

        , tracking_number = #{trackingNumber}

WHERE order_id = #{orderId}

